// 安全修复方案 1: 使用参数化命令（推荐）
import { spawn } from 'child_process';

export async function pingHost(target: string): Promise<string> {
  // 1. 使用 spawn 而非 exec，避免 shell 解析
  // 2. 将命令和参数分开传递，作为数组参数
  // 3. 不使用 shell: true 选项
  return new Promise((resolve, reject) => {
    spawn('ping', ['-c', '4', target])
      .stdout.on('data', (data) => resolve(data.toString()))
      .stderr.on('data', (data) => reject(new Error(data.toString())))
      .on('error', reject);
  });
}

// 安全修复方案 2: 输入验证和白名单（辅助）
import { isIP } from 'net';

export async function pingHost(target: string): Promise<string> {
  // 1. 验证输入必须是有效的 IP 地址或域名
  const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
  const domainPattern = /^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;

  if (!ipPattern.test(target) && !domainPattern.test(target)) {
    throw new Error('Invalid target: must be a valid IP address or domain name');
  }

  // 2. 使用参数化命令
  return new Promise((resolve, reject) => {
    spawn('ping', ['-c', '4', target])
      .stdout.on('data', (data) => resolve(data.toString()))
      .stderr.on('data', (data) => reject(new Error(data.toString())))
      .on('error', reject);
  });
}

